float TAU = 6.28318;

// Cycle through a color palette with a cosine wave
vec3 palette( float t ) {
    // How does this workkkkkk
    vec3 offset = vec3(0.3, 0.4, 0.2);
    vec3 amplitude = vec3(0.1, 0.1, 0.2);
    vec3 frequency = vec3(1.0, 1.0, 1.0);
    vec3 phase = vec3(0.263, 0.416, 0.557);

    return offset + amplitude * cos(TAU * (frequency * t + phase));

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from -1 to 1)
    // (-1,-1) = bottom left corner
    // (1,1) = top right corner
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;

    uv *= 4.;
    uv.y = (fract(uv.y) / 1.) +.5;
    uv.x = (fract(uv.x) / 0.5);

    float newTime = iTime * 2.5;
    // Default background color changes with time
    vec3 color = vec3(0.0);//palette(newTime);

    // Sine wave based on x coordinate of pixel
    // the uv.y will be the pixels y
    // if uv.y is "higher up" than the sin-esque functions value
    // then we override the current color value with that one
    if (
        distance(vec2(1.0),vec2(uv)) - 0.1 
        < 
        (
            clamp(sin(
                (uv.x) + newTime), -1.,0.2)
        )
    ) {
        // offset iTime by a different amount than above
        color = palette(newTime / 7.);
    }




    vec2 l = vec2(uv.x,color);
    // Output to screen
    fragColor = vec4(color, 1.0);
}
